import json, subprocess, time
from datetime import datetime, timezone
from pathlib import Path
root=Path('code/V4/runs/R67_supervised_contrastive_full18')
step='1465.97'
session='r67_final_test'
terminal_failures={'FAILED','TIMEOUT','CANCELLED','OUT_OF_MEMORY','NODE_FAIL','BOOT_FAIL','PREEMPTED','DEADLINE'}
required=['test_results_A.json','test_results_B.json','test_results.json','test_process_receipt.json']
next_poll=time.monotonic()+240
while True:
    while time.monotonic()<next_poll:
        time.sleep(min(30,next_poll-time.monotonic()))
    record={'observed_utc':datetime.now(timezone.utc).isoformat(),'slurm_step':step,'tmux_session':session}
    try:
        tmux=subprocess.run(['tmux','has-session','-t','='+session],capture_output=True,text=True,timeout=20)
        record.update(tmux_returncode=tmux.returncode,tmux_stderr=tmux.stderr.strip())
        record['tmux_terminal']=tmux.returncode==1 and ('session' in tmux.stderr.lower() or 'no server running' in tmux.stderr.lower())
    except subprocess.TimeoutExpired:
        record.update(tmux_returncode=None,tmux_stderr='observation timeout',tmux_terminal=False)
    try:
        sacct=subprocess.run(['sacct','-j',step,'--noheader','--parsable2','--format=JobIDRaw,JobName,State,ExitCode,ElapsedRaw,Start,End,NodeList'],capture_output=True,text=True,timeout=30)
        record.update(sacct_returncode=sacct.returncode,scheduler_evidence=sacct.stdout.strip(),scheduler_stderr=sacct.stderr.strip())
        fields=next((line.split('|') for line in sacct.stdout.splitlines() if line.split('|')[0]==step),[])
        if sacct.returncode==0 and len(fields)>=8:
            record.update(state=fields[2],exit_code=fields[3],elapsed_seconds=int(fields[4]))
        else:
            record.update(state='UNKNOWN',exit_code=None,elapsed_seconds=None)
    except (subprocess.TimeoutExpired,ValueError):
        record.update(state='UNKNOWN',exit_code=None,elapsed_seconds=None,scheduler_evidence='observation timeout or unparsable response')
    p=root/'test_progress.json'
    if p.exists():
        try:
            progress=json.loads(p.read_text())
            record['progress']={key:progress.get(key) for key in ['status','arm','completed_arms','recorded_utc']}
        except json.JSONDecodeError:
            record['progress']='transient incomplete JSON'
    record['completed_artifacts']=[name for name in required if (root/name).exists()]
    with (root/'monitor_test.jsonl').open('a') as stream:
        stream.write(json.dumps(record)+'\\n')
    print(json.dumps(record),flush=True)
    state=record['state'].split()[0].rstrip('+')
    if state in terminal_failures:
        raise SystemExit(2)
    if state=='COMPLETED' and record['exit_code']=='0:0' and record['tmux_terminal'] and len(record['completed_artifacts'])==len(required):
        raise SystemExit(0)
    if state=='COMPLETED' and record['exit_code']"'!='"'0:0':
        raise SystemExit(2)
    next_poll=time.monotonic()+240
PY"

